import hashlib
import time
import os
import unicodedata
from collections import defaultdict
from typing import Optional, Dict, Tuple

# Secure password storage using PBKDF2 with per-user salt
class PasswordStore:
    def __init__(self):
        self._store: Dict[str, Tuple[bytes, bytes]] = {}  # username -> (salt, hash)

    def register(self, username: str, password: str):
        salt = os.urandom(32)
        pw_hash = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 310000)
        self._store[username] = (salt, pw_hash)

    def verify(self, username: str, password: str) -> bool:
        if username not in self._store:
            return False
        salt, stored_hash = self._store[username]
        pw_hash = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 310000)
        return pw_hash == stored_hash


class RateLimiter:
    """Tracks failed login attempts per account to prevent brute-force."""

    MAX_ATTEMPTS = 5
    LOCKOUT_DURATION = 300  # 5 minutes

    def __init__(self):
        self._attempts: Dict[str, list] = defaultdict(list)
        self._lockouts: Dict[str, float] = {}

    def _normalize_identifier(self, identifier: str) -> str:
        """Normalize the identifier for consistent tracking.
        Uses NFC normalization to handle equivalent Unicode representations."""
        return unicodedata.normalize('NFC', identifier)

    def is_locked(self, identifier: str) -> bool:
        key = self._normalize_identifier(identifier)
        if key in self._lockouts:
            if time.time() - self._lockouts[key] < self.LOCKOUT_DURATION:
                return True
            else:
                del self._lockouts[key]
                self._attempts[key] = []
        return False

    def record_failure(self, identifier: str):
        key = self._normalize_identifier(identifier)
        self._attempts[key].append(time.time())
        # Only count recent attempts (within lockout window)
        cutoff = time.time() - self.LOCKOUT_DURATION
        self._attempts[key] = [t for t in self._attempts[key] if t > cutoff]
        if len(self._attempts[key]) >= self.MAX_ATTEMPTS:
            self._lockouts[key] = time.time()

    def reset(self, identifier: str):
        key = self._normalize_identifier(identifier)
        self._attempts.pop(key, None)
        self._lockouts.pop(key, None)


class AuthService:
    def __init__(self):
        self.password_store = PasswordStore()
        self.rate_limiter = RateLimiter()
        self._sessions: Dict[str, dict] = {}

    def register_user(self, username: str, password: str) -> bool:
        """Register a new user. Username is stored in NFC-normalized form."""
        normalized = unicodedata.normalize('NFC', username.strip())
        if not normalized or len(normalized) > 64:
            return False
        if normalized in self.password_store._store:
            return False
        self.password_store.register(normalized, password)
        return True

    def _get_tracking_key(self, username: str, source_ip: str) -> str:
        """Build the key used for rate-limiting.
        Combines username and IP to prevent distributed attacks."""
        # Normalize username for rate limiting consistency
        norm_user = unicodedata.normalize('NFKC', username.lower())
        return f"{norm_user}@{source_ip}"

    def authenticate(self, username: str, password: str, source_ip: str) -> Optional[str]:
        """Authenticate a user. Returns session token or None."""
        tracking_key = self._get_tracking_key(username, source_ip)

        # Check rate limit
        if self.rate_limiter.is_locked(tracking_key):
            return None

        # Normalize username for lookup (same as registration)
        lookup_name = unicodedata.normalize('NFC', username.strip())

        # Verify credentials
        if self.password_store.verify(lookup_name, password):
            self.rate_limiter.reset(tracking_key)
            token = os.urandom(32).hex()
            self._sessions[token] = {'user': lookup_name, 'created': time.time()}
            return token
        else:
            self.rate_limiter.record_failure(tracking_key)
            return None


def main():
    auth = AuthService()

    # Register admin user
    auth.register_user('admin', 'super_secret_password_2024!')
    auth.register_user('alice', 'alice_password_123')

    # Normal login attempt
    result = auth.authenticate('admin', 'super_secret_password_2024!', '192.168.1.1')
    assert result is not None, "Valid login should succeed"

    # Brute force attempt - should get locked out
    for i in range(6):
        auth.authenticate('admin', f'wrong_password_{i}', '10.0.0.1')

    # Should be locked out now
    result = auth.authenticate('admin', 'super_secret_password_2024!', '10.0.0.1')
    assert result is None, "Should be locked out after 5 failures"

    print("All assertions passed.")


if __name__ == '__main__':
    main()
